/* ===== a customer file in a shape the app does not know: sent to the admins, who see it on Home and work it out (with Claude) ===== */
var IMP_LAST = null, IMP_FILE = '', IMP_SAMPLES = {};
/* what a file looked like to the app (first rows or text) – sent with a request for a new shape */
function impKeep(rows, text) { IMP_ALL += '\n' + (rows ? rows.map(function (r) { return (r || []).join(' | '); }).join('\n') : String(text || '')); var t = rows ? rows.slice(0, 45).map(function (r) { return r.map(function (c) { return String(c == null ? '' : c).replace(/\s+/g, ' ').trim(); }).join(' | ').replace(/( \| )+$/, ''); }).filter(function (l) { return l.replace(/[ |]/g, ''); }).join('\n') : String(text || '').replace(/[ \t]+/g, ' ').slice(0, 3500);
  var o = IMP_SAMPLES[IMP_FILE] || ''; if (o.length < 4000 && t) IMP_SAMPLES[IMP_FILE] = (o ? o + '\n---\n' : '') + t.slice(0, 4000 - o.length); IMP_LAST = { name: IMP_FILE, text: IMP_SAMPLES[IMP_FILE] || '' }; }
function shapeReqs() { var L = LS.get('shapeReq', []) || [], gone = LS.get('shapeReqDone', {}) || {}; return L.filter(function (r) { return r && r.id && !gone[r.id]; }); }
function shapeReqSend(p, odd) { var me = S.me ? S.me.name : 'someone', smp = IMP_LAST ? IMP_LAST : null, at = Date.now();
  var recs = odd.map(function (o, i) { return { id: 'sr' + at.toString(36) + i, file: o.name, why: o.why, by: me, at: at, co: p && p.company ? p.company.name : '', job: p ? p.id : '', sample: IMP_SAMPLES[o.name] || (smp && smp.name === o.name ? smp.text : '') }; });
  LS.set('shapeReq', (LS.get('shapeReq', []) || []).concat(recs)); toast('Sent to the admins – they get it on their Home'); }
function shapeReqCard() { if (!certAdmin()) return ''; var L = shapeReqs(); if (!L.length) return '';
  return '<section class="hblk shrq"><div class="shrqh"><b>📥 New file shapes – need admin (' + L.length + ')</b><small>Customer files the app could not read. Open one, work it out with Claude, then mark it done.</small></div>' + L.slice(-4).reverse().map(function (r) { return '<button class="shrqr" data-shrq="' + esc(r.id) + '"><b>' + esc(r.file) + '</b><small>' + esc([r.co, r.by, new Date(r.at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })].filter(Boolean).join(' · ')) + '</small><span>›</span></button>'; }).join('') + '</section>'; }
function shapeReqSheet(id) { var r = shapeReqs().filter(function (x) { return x.id === id; })[0]; if (!r) return;
  var ask = 'A customer of our calibration lab sent a file our Certificates app cannot read (file: ' + r.file + (r.co ? ', customer: ' + r.co : '') + '). Why: ' + (r.why || []).join('; ') + '.\nMake the app read this shape (or tell me how to turn it into our Excel template). Here is what the app saw in it:\n----\n' + (r.sample || '(nothing)') + '\n----';
  openSheet(function () { return { wide: 1, title: '📥 ' + esc(r.file), body: '<div class="note">' + esc([r.co, 'sent by ' + r.by, new Date(r.at).toLocaleString('en-GB')].filter(Boolean).join(' · ')) + '<br><b>Why:</b> ' + esc((r.why || []).join(' · ')) + '</div>' +
      '<div class="shrqs"><div class="shpl">What the app saw in the file</div><pre>' + esc(r.sample || '(nothing could be read)') + '</pre></div><div class="small">Ask the person for the file itself if you need it. “Copy for Claude” copies the request and the text above – paste it in the Certificates chat with Claude.</div>',
    foot: '<button class="btn ghost" id="srX">Close</button><button class="btn ghost" id="srCp">📋 Copy for Claude</button><button class="btn" id="srOk">✓ Done – remove it</button>',
    mount: function () { $('#srX').onclick = closeSheet; $('#srCp').onclick = function () { var ok = function () { toast('Copied – paste it in the chat with Claude'); }; if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(ask).then(ok, function () { window.prompt('Copy this', ask); }); else window.prompt('Copy this', ask); };
      $('#srOk').onclick = function () { var d = LS.get('shapeReqDone', {}) || {}; d[r.id] = Date.now(); LS.set('shapeReqDone', d); closeSheet(); render(); toast('Removed'); }; } }; }); }
document.addEventListener('click', function (e) { var b = e.target && e.target.closest && e.target.closest('[data-shrq]'); if (b) { e.preventDefault(); shapeReqSheet(b.dataset.shrq); } });
